private static boolean dfs(char[][] grid, int x, int y) {
    if (x < 0 || y < 0 || x >= grid.length || y >= grid[x].length || grid[x][y] != '*')
        return false;

    grid[x][y] = '0'; // Mark the cell as visited

    // Recursively check the adjacent cells
    boolean moveUp = dfs(grid, x - 1, y);
    boolean moveDown = dfs(grid, x + 1, y);
    boolean moveLeft = dfs(grid, x, y - 1);
    boolean moveRight = dfs(grid, x, y + 1);

    // If a connected land cell contains an oil pocket, return true
    return moveUp && moveDown && moveLeft && moveRight;
}

