public static int maxRegions(int N) {
    // Base cases for N = 0, 1, and 2
    if (N == 0) return 0;
    if (N == 1) return 2;
    if (N == 2) return 8;

    // General case with a recurrence relation
    int[] dp = new int[N + 1];
    dp[0] = 0;
