public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the start and end coordinates are within the grid boundaries
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Create a visited matrix to track visited cells
    boolean[][] visited = new boolean[n][n];

    // Recursively traverse the maze
    if (visitAndTraverse(start, end, visited, paths)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean visitAndTraverse(int[] current, int[] destination, boolean[][] visited, int[][] paths) {
    int rows = paths.length;
    int cols = paths[0].length;

    // Mark the current cell as visited
    visited[current[0]][current[1]] = true;

    // Define the four possible directions
    int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    // Iterate through each direction
    for (int[] dir : directions) {
        int nextX = current[0] + dir[0];
        int nextY = current[1] + dir[1];

        // Check if the next cell is within the grid boundaries and is not visited
        if (nextX >= 0 && nextX < cols && nextY >= 0 && nextY < rows && !visited[nextX][nextY]) {
            // Check if the destination coordinates are unreachable
            if (nextX == destination[0] && nextY == destination[1]) {
                continue;
            }

            // Recursively traverse the next cell
            if (visitAndTraverse(new int[]{nextX, nextY}, destination, visited, paths)) {
                return true;
            }
        }
    }

    // If no path is found, return false
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    return bfs(n, start, end, paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean bfs(int n, int[] start, int[] end, int[][] paths, boolean[] visited) {
    if (visited[start[0]][start[1]]) {
        return false;
    }
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0]][start[1]] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (Arrays.equals(current, end)) {
            return true;
        }

        for (int[] path : paths) {
            int nextX = current[0] + path[0];
            int nextY = current[1] + path[1];
            if (nextX >= 0 && nextX < n && nextY >= 0 && nextY < n && !visited[nextX][nextY]) {
                queue.offer(new int[]{nextX, nextY});
                visited[nextX][nextY] = true;
            }
        }
    }

    return false;
}

