    boolean visited[] = new boolean[n];
    return dfs(graph, start, end, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(boolean[][] graph, int[] start, int[] end, boolean[] visited) {
    int x = start[0];
    int y = start[1];
    if (x == end[0] && y == end[1]) return true;
    visited[x][y] = true;
    for (int[] dir : new int[][]{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}) {
        int newX = x + dir[0];
        int newY = y + dir[1];
        if (newX >= 0 && newX < graph.length && newY >= 0 && newY < graph.length && !visited[newX][newY] && graph[newX][newY]) {
            if (dfs(graph, new int[]{newX, newY}, end, visited)) return true;
        }
    }
    return false;
}

