    if (isPointValid(start, n)) {
        // Perform a DFS to check if the end point can be reached
        boolean isReachable = performDFS(start, end, n, visited, paths);

        // Return the appropriate message based on the result of the DFS
        if (isReachable) {
            return "can be travelled";
        } else {
