private static boolean isPointValid(int[] point, int n) {
    // Check if the point coordinates are within the bounds of the n-teresting space
    return point[0] >= 0 && point[0] < n && point[1] >= 0 && point[1] < n;
}

private static boolean performDFS(int[] current, int[] target, int n, boolean[][] visited, int[][] paths) {
    // Base case: if the current point is the target, return true
    if (Arrays.equals(current, target)) {
        return true;
    }

    // Mark the current point as visited
    visited[current[0]][current[1]] = true;

    // Check the next positions
    for (int[] path : paths) {
        // Calculate the next position based on the current position and the path
