public boolean canArrange(int[] arr, int k) {
    int count = 0;
    Map<Integer, Integer> map = new HashMap<>();

    for (int num : arr) {
        int remainder = num % k;
        if (remainder == 0) {
            count++;
        } else if (remainder == k / 2) {
            if (count == 1) {
                count--;
                continue;
            }
            return false;
        }
        int complement = k - remainder;
        if (map.containsKey(complement)) {
            if (count > 0 && complement > 0 || count == 0) {
                count--;
            } else return false;
        }
        map.put(remainder, map.getOrDefault(remainder, 0) + 1);
    }

    return count == 0;
}

public boolean canArrange(int[] arr, int k) {
    int[] counts = new int[k];
    for (int num : arr) {
        int remainder = num % k;
        counts[remainder]++;
    }

    for (int i = 0; i <= k / 2; i++) {
        if ((i % 2 == 0 && counts[i] != counts[k - i]) ||
            (i % 2 != 0 && counts[i] < counts[k - i])) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    HashMap<Integer, Integer> map = new HashMap<>();
    for (int i = 0; i < n; i++) {
        int mod = arr[i] % k;
        if (mod == 0) {
            map.put(0, map.getOrDefault(0, 0) + 1);
        } else {
            map.put(mod, map.getOrDefault(mod, 0) + 1);
        }
    }
    int count = 0;
    if (map.containsKey(0)) {
        count += map.get(0) / 2;
    }
    for (int i = 1; i < k / 2 + 1; i++) {
        if (map.containsKey(k - i) && map.containsKey(i)) {
            count += Math.min(map.get(i), map.get(k - i));
        }
    }
    return count >= n / 2;
}

public boolean canArrange(int[] arr, int k) {
    HashMap<Integer, Integer> remainders = new HashMap<>();
    for (int num : arr) {
        remainders.put(num % k, remainders.getOrDefault(num % k, 0) + 1);
    }
    for (int i = 0; i < k / 2; i++) {
        if (remainders.containsKey(i)) {
            int count = remainders.get(i);
            if (i != 0 && count != remainders.get(k - i)) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    for (int i = 0; i < arr.length; i++) {
        // Calculate the remainder when the current element is divided by k
        int remainder = arr[i] % k;
        // If the remainder is 0, there can be a pair of elements with a sum divisible by k
        if (remainder == 0) return true;
        // If a pair with the complement of the remainder exists (k - remainder), we can form a valid pair
        if (remainder > 0 && remainder % k == 0) return true;
    }
    return false;
}

public static int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build the adjacency list graph based on the edges
    List<List<Integer>> graph = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    // Define a recursive function to calculate the minimum path time to collect apples
    return dfs(0, hasApple, graph);
}

private static int dfs(int node, boolean[] hasApple, List<List<Integer>> graph) {
    if (node == -1) // Special case: direct parent node
        return 0;

    int result = 0; // Local result for this node
    for (int child : graph.get(node)) {
        if (dfs(child, hasApple, graph) > 0 || hasApple[child]) {
            result += 2; // Incorporate the cost of both steps and self
        }
    }

    return result;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
    for (int[] edge : edges) {
        adj.get(edge[0]).add(edge[1]);
        adj.get(edge[1]).add(edge[0]);
    }

    Set<Integer> candidates = new HashSet<>();
    min(a -> hasApple[a],candidates );
    int res = 0;
    for (int candidate : candidates) res += 2;
    return res;

}

private void min(IntPredicate p, Set<Integer> candidates) {
    if (!p.test(0)) return;
    candidates.add(0);
    for (Integer next : adj.get(0)) min(p,candidates);
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int time = 0;
    List<List<Integer>> graph = buildGraph(n, edges);
    boolean[] visited = new boolean[n];

    for (int i = 0; i < n; i++) {
        if (hasApple[i] || (graph.get(i).size() > 0 && !visited[i])) {
            time += 2;
            visited[i] = true;
            processChildren(i, graph, visited);
        }
    }

    return time;
}

private void processChildren(int parent, List<List<Integer>> graph, boolean[] visited) {
    for (int child : graph.get(parent)) {
        if (!visited[child]) {
            visited[child] = true;
            if (hasApple[child] || processChildren(child, graph, visited)) {
                time += 2;
            }
        }
    }
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] edge : edges) {
        graph[edge[0]].add(edge[1]);
        graph[edge[1]].add(edge[0]);
    }
    Set<Integer> visited = new HashSet<>();
    visited.add(0);
    int time = 0;
    queue<Integer> q = new LinkedList<>();
    q.add(0);
    while (!q.isEmpty()) {
        int size = q.size();
        for (int i = 0; i < size; i++) {
            int node = q.poll();
            for (int next : graph[node]) {
                if (visited.contains(next)) continue;
                visited.add(next);
                time += hasApple[next] ? 2 : 0;
                q.add(next);
            }
        }
    }
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] graph = new int[n];
    for (int[] edge : edges) {
        int u = edge[0], v = edge[1];
        graph[u] |= 1 << v; // 使用位运算标记有边
        graph[v] |= 1 << u; // 正反边用 or 运算符
    }

    // 使用递归处理 if 有边 | 节点是apple 节点有苹果的情况
    return dfs(0, graph, hasApple, new boolean[n]);
}

private int dfs(int pos, int[] graph, boolean[] hasApple, boolean[] visited) {
    if (visited[pos]) {
        return 0;
    }
    visited[pos] = true;
    int totalTime = hasApple[pos] ? 2 : 0;

    // 前向遍历找到所有的苹果
    for (int childPos = 0; childPos < graph[pos]; childPos <<= 1) {
        if (!visited[childPos]) {
            totalTime += dfs(childPos, graph, hasApple, visited);
        }
    }

    return totalTime;
}

public String sortString(String s) {
    StringBuilder sb = new StringBuilder();
    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> Integer.compare(b, a));

    for (char c : s.toCharArray()) {
        minHeap.offer(c);
        maxHeap.offer(c);
    }

    while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
        if (!minHeap.isEmpty()) {
            char c = minHeap.poll();
            if (sb.length() == 0 || c < sb.charAt(sb.length() - 1)) {
                sb.append(c);
            } else {
                maxHeap.offer(c);
            }
        }
        if (!maxHeap.isEmpty()) {
            char c = maxHeap.poll();
            if (sb.length() == 0 || c > sb.charAt(sb.length() - 1)) {
                sb.append(c);
            } else {
                minHeap.offer(c);
            }
        }
    }

    return sb.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    char[] arr = s.toCharArray();
    Arrays.sort(arr);
    StringBuilder sb = new StringBuilder();

    while (true) {
        for (char c : arr) {
            if (sb.length() > 0 && Math.abs((int)c - (int)sb.charAt(sb.length() - 1)) > 1) {
                continue;
            }
            sb.append(c);
        }

        for (int i = arr.length - 1; i >= 0; i--) {
            if (sb.length() > 0 && Math.abs((int)c - (int)sb.charAt(sb.length() - 1)) > 1) {
                continue;
            }
            sb.append(arr[i]);
        }

        if (sb.length() == s.length()) {
            break;
        }
    }

    return sb.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    int[] charCount = new int[129]; // Assuming ASCII character set

    // Count occurrences of each character
    for (char c : s.toCharArray()) {
        charCount[c]++;
    }

    // Process characters sorted by their values
    for (int i = 0; i < 129; i++) {
        // Append characters the smallest amount of times
        appendCharacter(s, result, charCount, i);
    }

    return result.toString();
}

private void appendCharacter(String s, StringBuilder result, int[] charCount, int startValue) {
    int value = startValue;
    while (charCount[value] > 0) {
        result.append((char) value);
        charCount[value]--;
    }
}

public String sortString(String s) {
    TreeMap<Character, Integer> charCountMap = new TreeMap<>();
    for (char c : s.toCharArray()) {
        charCountMap.put(c, charCountMap.getOrDefault(c, 0) + 1);
    }

    StringBuilder result = new StringBuilder();
    while (charCountMap.size() > 0) {
        // Pick the smallest character
        for (Map.Entry<Character, Integer> entry : charCountMap.entrySet()) {
            if (entry.getValue() > 0) {
                result.append(entry.getKey());
                entry.setValue(entry.getValue() - 1);
                break;
            }
        }

        // Remove empty entries after picking the smallest character
        charCountMap.entrySet().removeIf(entry -> entry.getValue() == 0);

        // Check if the character set is empty at this stage
        if (charCountMap.isEmpty()) {
            break;
        }

        // Pick the largest character
        for (Map.Entry<Character, Integer> entry : charCountMap.descendingMap().entrySet()) {
            if (entry.getValue() > 0) {
                result.append(entry.getKey());
                entry.setValue(entry.getValue() - 1);
                break;
            }
        }

        // Remove empty entries after picking the largest character
        charCountMap.entrySet().removeIf(entry -> entry.getValue() == 0);
    }

    return result.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (s.length() > 0) {
        int smallestIndex = 0;
        int smallestChar = s.charAt(smallestIndex);
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < smallestChar) {
                smallestIndex = i;
                smallestChar = s.charAt(i);
            }
        }

        // Append the smallest character
        result.append(s.charAt(smallestIndex));
        s = s.substring(0, smallestIndex) + s.substring(smallestIndex + 1);

        // Append the largest character
        int largestIndex = s.length() - 1;
        int largestChar = s.charAt(largestIndex);
        for (int i = largestIndex - 1; i >= 0; i--) {
            if (s.charAt(i) > largestChar) {
                largestIndex = i;
                largestChar = s.charAt(i);
            }
        }

        // Append the largest character
        result.append(s.charAt(largestIndex));
        s = s.substring(0, largestIndex) + s.substring(largestIndex + 1);
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    if (totalSum % 2 != 0) {
        return false;
    }
    int targetSum = totalSum / 2;
    return canSplitArrayWith SameAverage(nums, 0, n - 1, targetSum);
}

private boolean canSplitArrayWithSameAverage(int[] nums, int start, int end, int targetSum) {
    if (start == end) {
        return nums[start] == targetSum;
    }
    if (targetSum < nums[start] || (end - start + 1) * targetSum < totalSum - targetSum) {
        return false;
    }
    for (int i = start; i <= end; i++) {
        if (nums[start] + nums[i] == targetSum) {
            if (canSplitArrayWithSameAverage(nums, i + 1, end, targetSum - nums[i])) {
                return true;
            }
            if (i + 1 < end && canSplitArrayWithSameAverage(nums, start + 1, i, targetSum - nums[start])) {
                return true;
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums.length < 2) {
        return false;
    }
    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    if (totalSum % 2 != 0) {
        return false;
    }
    double targetSum = totalSum / 2.0;
    int sumLeft = 0;
    int[] sums = new int[nums.length];
    for (int i = nums.length - 1; i >= 0; i--) {
        if (sumLeft + nums[i] >= targetSum) {
            sums[i] = sumLeft;
            sumLeft = targetSum;
        } else {
            sumLeft += nums[i];
            sums[i] = sumLeft;
        }
        if (sumLeft == targetSum) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    if (sum % 2 != 0) {
        return false;
    }
    int target = sum / 2;
    int tempSum = 0;
    for (int i = 0; i < nums.length; i++) {
        tempSum += nums[i];
        if (tempSum == target) {
            int subSize = nums.length - i - 1;
            if (isAverageEqual(tempSum, i + 1, subSize, nums)) {
                return true;
            }
        }
    }
    return false;
}

private boolean isAverageEqual(int tempSum, int start, int size, int[] nums) {
    int sum = 0;
    for (int i = start; i < start + size; i++) {
        sum += nums[i];
    }
    return sum * 2 == tempSum;
}

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int halfSum = totalSum / 2;
    int length = nums.length;
    int[][] memo = new int[length + 1][halfSum + 1];
    for (int[] row : memo) {
        Arrays.fill(row, -1);
    }
    return splitArraySameAverageRecursive(nums, 0, halfSum, memo);
}

private boolean splitArraySameAverageRecursive(int[] nums, int index, int remaining, int[][] memo) {
    if (index == nums.length) {
        return remaining == 0;
    }
    if (memo[index][remaining] != -1) {
        return memo[index][remaining] == 1;
    }
    boolean result = splitArraySameAverageRecursive(nums, index + 1, remaining, memo)
            || splitArraySameAverageRecursive(nums, index + 1, remaining - nums[index], memo);
    memo[index][remaining] = result ? 1 : 0;
    return result;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = Arrays.stream(nums).sum();
    int target = sum / 2;
    int count = 0;
    Map<Integer, Integer> map = new HashMap<>();
    map.put(0, 1);
    for (int i = 0; i < nums.length; i++) {
        count += nums[i];
        if (map.containsKey(count - target)) {
            return true;
        }
        map.put(count, map.getOrDefault(count, 0) + 1);
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int dp = 0;
    int w1 = 0;
    int w2 = 0;

    for (int i = 0; i < cost.length; i++) {
        dp = Math.min(w1, w2) + cost[i];
        w1 = w2;
        w2 = dp;
    }

    return dp;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n <= 1) return cost[0];

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i-1], dp[i-2]);
    }

    return Math.min(dp[n-1], dp[n-2]);
}

