public boolean hasAllCodes(String s, int k) {
    if (k > s.length()) return false;
    if (k == 1) return s.replace("0", "").replace("1", "").isEmpty();

    int n = 1 << k;
    boolean[] seen = new boolean[n];
    int mask = (1 << k) - 1;

    for (int i = 0; i <= s.length() - k; i++) {
        int current = Integer.parseInt(s.substring(i, i + k), 2);
        if (current > mask) break;
        if (seen[current]) return false;
        seen[current] = true;
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    Set<Integer> set = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        int num = Integer.parseInt(s.substring(i, i + k), 2);
        if (!set.add(num)) {
            return false;
        }
    }
    return set.size() == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) return false;
    Set<String> set = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        String sub = s.substring(i, i + k);
        if (!set.contains(sub)) set.add(sub);
    }
    return set.size() == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int mask = (1 << k) - 1;
    boolean[] seen = new boolean[mask + 1];

    for (int i = 0; i < n - k + 1; i++) {
        int current = Integer.parseInt(s.substring(i, i + k), 2);
        if (!seen[current]) {
            seen[current] = true;
        } else {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int requiredLengthOfSet = (int) Math.pow(2, k);
    boolean[] result = new boolean[requiredLengthOfSet];

    for (int i = 0; i <= n - k; i++) {
        result[Integer.parseInt(s.substring(i, i + k), 2)] = true;
    }

    for (boolean temp : result) {
        if (!temp) {
            return false;
        }
    }

    return true;
}

