public int minInsertions(String s) {
    int balance = 0;
    int deficit = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else {
            balance--;
            if (balance < 0) {
                balance = 1; // only need one left parenthesis
                deficit++;
            }
        }
    }
    return balance + deficit;
}

public int minInsertions(String s) {
    int balance = 0, minInsertions = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else {
            balance--;
            if (balance < 0) {
                minInsertions++;
                balance = 1;
            }
        }
    }
    minInsertions += balance;
    return minInsertions;
}

public int minInsertions(String s) {
    int left = 0, right = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch == '(') {
            left++;
        } else {
            right++;

            if (right > left) {
                insertions += left;
                left = 0;
            }
        }
    }

    insertions += right + Math.max(left, right);

    return insertions;
}

