public int maxAbsoluteSum(int[] nums) {
    int minSum = 0, maxSum = 0, totalSum = 0;
    for (int num : nums) {
        totalSum += num;
        minSum = Math.min(minSum, totalSum);
        maxSum = Math.max(maxSum, totalSum);
    }
    return Math.max(maxSum, -minSum);
}

