    for (int num : nums) {
        maxSum = Math.max(num, maxSum + num);
        minSum = Math.min(num, minSum + num);

        maxAbsSum = Math.max(maxAbsSum, Math.abs(maxSum));
        maxAbsSum = Math.max(maxAbsSum, Math.abs(minSum));
    }

    return maxAbsSum;
}

