    return result;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fibs = new ArrayList<>();
    int i = 1;
    while (i <= k) {
        fibs.add(i);
        i += fibs.get(fibs.size() - 1);
    }
    int count = 0;
    for (int j = fibs.size() - 1; j >= 0 && k > 0; j--) {
        if (fibs.get(j) <= k) {
            k -= fibs.get(j);
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    int fib1 = 1;
    int fib2 = 1;
    int count = 0;

    while (k > 0) {
        if (k >= fib2) {
            k -= fib2;
            count++;
        } else {
            // Push fib1 back to k and use fib2
            int temp = k;
            k -= fib1;
            fib1 += fib2;
            fib2 = temp;
        }
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fibNumbers = new ArrayList<>();
    fibNumbers.add(0);
    fibNumbers.add(1);
    int n = 1;
    while (fibNumbers.get(n) <= k) {
        fibNumbers.add(fibNumbers.get(n - 1) + fibNumbers.get(n - 2));
        n++;
    }
    Collections.reverse(fibNumbers);

    int count = 0;
    for (int i = fibNumbers.size() - 1; i >= 0; i--) {
        while (k >= fibNumbers.get(i)) {
            count++;
            k -= fibNumbers.get(i);
        }
        if (k == 0) {
            break;
        }
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    int F1 = 1, F2 = 1, F3 = 2;
    while (F3 <= k) {
        F1 = F2;
        F2 = F3;
        F3 = F1 + F2;
    }

    int count = 0;
    while (k > 0) {
        if (k >= F3) {
            k -= F3;
            count++;
        } else if (k >= F2) {
            k -= F2;
            count++;
        } else {
            k -= F1;
            count++;
        }
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fibs = new ArrayList<>();
    int[] memo = new int[k + 1];
    int currFib = 1;
    int prevFib = 1;

    while (currFib <= k) {
        fibs.add(currFib);
        memo[currFib] = 1;
        int newFib = currFib + prevFib;
        currFib = prevFib;
        prevFib = newFib;
    }

    int minFib = k;
    int[] usedFibs = new int[fibs.size()];
    for (int i = fibs.size() - 1; i >= 0; i--) {
        if (memo[fibs.get(i)] == 1) {
            usedFibs[k - fibs.get(i)]++;
            k -= fibs.get(i);
            minFib = Math.min(minFib, usedFibs[k - fibs.get(i)]);
        }
        if (k == 0) break;
    }
    return minFib;
}

