public String makeGood(String s) {
    StringBuilder sb = new StringBuilder();
    int i = 0;
    while (i < s.length()) {
        if (i + 1 < s.length() && sb.length() > 0 && sb.charAt(sb.length()-1) == Character.toUpperCase(s.charAt(i)) && s.charAt(i + 1) == Character.toLowerCase(s.charAt(i))) {
