public String makeGood(String s) {
    StringBuffer buffer = new StringBuffer();
    int i = 0;
    while (i < s.length() - 1) {
        if (Math.abs((int) s.charAt(i) - (int) s.charAt(i + 1)) == 32) {
            buffer.append(s.charAt(i));
            buffer.append(s.charAt(i + 1));
            i += 2;
        } else {
            buffer.append(s.charAt(i));
            i++;
        }
