public int maxUniqueSplit(String s) {
    Set<String> seen = new HashSet<>();
    int result = 0;
    int left = 0;

    while (left <= s.length()) {
        if (seen.contains(s.substring(left))) {
            seen.clear();
            left++;
            result++;
        } else {
            seen.add(s.substring(left));
            left++;
        }
    }

    return result;
}

public int maxUniqueSplit(String s) {
    int max = 0;
    for (int i = 1; i <= s.length(); i++) {
        for (int start = 0; start <= s.length() - i; start++) {
            String sub = s.substring(start, start + i);
            if (!checkUnique(sub)) {
                break;
            }
            max++;
        }
    }
    return max;
}

private boolean checkUnique(String sub) {
    Set<Character> set = new HashSet<>();
    for (char c : sub.toCharArray()) {
        if (set.contains(c)) {
            return false;
        }
        set.add(c);
    }
    return true;
}

public int maxUniqueSplit(String s) {
