    int count = 1;

    for (int i = 0; i < s.length(); i++) {
        for (int j = i + 1; j <= s.length(); j++) {
            String substring = s.substring(i, j);
            if (seen.contains(substring)) break;
            seen.add(substring);
            count++;
            if (! isValid(s, seen)) return count - 1;
        }
    }

    return count;
}

private boolean isValid(String s, HashSet<String> seen) {
    for (int i = 0; i < s.length(); i++) {
        if (seen.contains(s.substring(0, i + 1))) return false;
    }
    return true;
}

