            if (set.size() > res) {
                res = set.size();
            }
            for (int j = 1; i + j <= s.length(); j++) {
                if (!set.contains(s.substring(i, i + j))) {
                    set.add(s.substring(i, i + j));
                    if (set.size() > res) {
                        res = set.size();
                    }
                }
            }
        }
        return res;
