public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) return 0;
    Map<String, Integer> count = new HashMap<>();
    boolean[] visited = new boolean[s.length()];
    return helper(s, "", count, visited);
}

private int helper(String s, String current, Map<String, Integer> count, boolean[] visited) {
    if (s.isEmpty()) return count.getOrDefault(current, 1);
    int maxUnique = 0;
    for (int i = 0; i < s.length(); i++) {
        if (!visited[i]) {
            visited[i] = true;
            String sub = s.substring(0, i + 1);
            count.put(sub, count.getOrDefault(sub, 0) + 1);
            if (count.get(sub) == 1) {
                maxUnique = Math.max(maxUnique, helper(s.substring(i + 1), current + sub, count, visited));
            }
            count.put(sub, count.get(sub) - 1);
            visited[i] = false;
        }
    }
    return maxUnique;
}

