public String getSmallestString(int n, int k) {
    if (n == 1) {
        return Character.toString((char) (k + 'a' - 1));
    }

    StringBuilder result = new StringBuilder();
    int remainder = k % 26;
    int base = 1 + ((k - remainder) / 26);

    if (remainder == 0) {
        for (int i = base; i < n; i++) {
            result.append('z');
        }
        result.append((char) (base + remainder));
    } else {
        for (int i = base; i < n; i++) {
            result.append((char) (base + remainder));
        }
        result.append((char) (base + remainder - 1));
    }

    return result.toString();
}

public String getSmallestString(int n, int k) {
    if (k == 1) {
        return "a";
    }
    StringBuilder str = new StringBuilder();
    for (int i = 0; i < n; i++) {
        if (k >= 26) {
            str.append('a');
            k -= 26;
        } else {
            str.append((char) ('a' + k));
            break;
        }
    }
    return str.toString();
}

public String getSmallestString(int size, int value) {
    // Check if the value is less than the smallest value possible with the size
    if (value < (size * (size + 1)) / 2) {
        throw new IllegalArgumentException("The value must be at least " + ((size * (size + 1)) / 2));
    }

    StringBuilder smallestString = new StringBuilder(size, 'a');
    int sum = 0;

    // Initialize the smallest string with the smallest letters
    for (int i = 0; i < size; i++) {
        sum += i + 1;
        smallestString.setCharAt(i, (char) ('a' + i));
    }

    // Adjust the string to meet the specified value
    int remaining = value % size;
    for (int i = 0; i < remaining; i++) {
        smallestString.setCharAt(i, (char) ('a' + 1 + i));
    }

    return smallestString.toString();
}

public String getSmallestString(int n, int k) {
    if (k <= n) {
        return Character.toString((char) (k + 96));
    } else {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append((char) (96 + (k / 26)));
            k = k % 26;
        }
        return sb.toString();
    }
}

public String getSmallestString(int n, int k) {
    char[] res = new char[n];
    for (int i = 0; i < n; i++) {
        res[i] = (char) ('a' + i);
        k -= i;
        while (k <= 0) {
            res[i]--;
            k += 26;
        }
    }
    return new String(res);
}

