public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNums = new ArrayList<>();
    if (low == 0) {
        steppingNums.add(0);
    }
    for (int num = low; num <= high; num++) {
        if (isSteppingNumber(num)) {
            steppingNums.add(num);
        }
    }
    steppingNums.sort(Integer::compare);
    return steppingNums;
}

private static boolean isSteppingNumber(int number) {
    String str = String.valueOf(number);
    for (int i = 1; i < str.length(); i++) {
        int currentDigit = (str.charAt(i) - '0');
        int previousDigit = (str.charAt(i - 1) - '0');
        if (Math.abs(currentDigit - previousDigit) != 1) {
            return false;
        }
    }
    return true;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    for (int i = 0; i <= 9; i++) {
        findSteppingNumbersHelper(i, low, high, result);
    }
    return result;
}

private static void findSteppingNumbersHelper(int num, int low, int high, List<Integer> result) {
    if (num >= low && num <= high) {
        result.add(num);
    }
    int next = num * 10 + num / 10 + 1;
    if (next <= high && next >= low) {
        findSteppingNumbersHelper(next, low, high, result);
    }
    next = num * 10 + num / 10 - 1;
    if (next <= high && next >= low) {
        findSteppingNumbersHelper(next, low, high, result);
    }
}

