private int case0(int n) {
    if (n < 0) {
        return -1;
    } else if (n <= 1) {
        return n;
    }
    return case0(n - 2) * 10 + (n - 1) * 10 + 0;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low == 0) {
            result.add(0);
            low = -1;
        }
        Queue<Integer> queue = new LinkedList<>();
        for (int i = low; i <= high; i += 1) {
            if (i >= 0) {
                queue.add(i);
            }
        }
        while (!queue.isEmpty()) {
            int current = queue.poll();
            if (current >= low && current <= high) {
                result.add(current);
            }
            int next = current + 1;
            int prev = current - 1;
            if (next <= high && (next < 10 || isSteppingNumber(next))) {
                queue.add(next);
            }
            if (prev >= low && (prev > -10 || isSteppingNumber(prev))) {
                queue.add(prev);
            }
        }
        result.sort((a, b) -> a - b);
        return result;
    }

