        for (int i = 1; i < numStr.length(); i++) {
            if (Math.abs(Integer.parseInt(String.valueOf(numStr.charAt(i - 1))) - Integer.parseInt(String.valueOf(numStr.charAt(i)))) != 1) {
                return false;
            }
        }
        return true;
    }

