public static int countDigitOne(int n) {
    if (n <= 0) return 0;

    int len = (int) Math.log10(n);
    int total = 0;

    // Count occurrences of 1 at each digit position from least significant to most significant
    for (int i = 0; i <= len; i++) {
        int base = (int) Math.pow(10, len - i);
        int high = n / base;
        int low = n % base;
        int range = high * base + Math.min(low, 1);
        total += high * (base - 1) * len + range;
    }

    return total;
}

