private static void permute(int[] arr, int start, int[] count) {
    if (start == arr.length) {
        count[0]++;
        return;
    }

    for (int i = start; i < arr.length; i++) {
        if (isSumPerfect(arr[start], arr[i])) {
            swap(arr, start, i);
            permute(arr, start + 1, count);
            swap(arr, start, i); // backtrack
        }
    }
}

private static boolean isSumPerfect(int a, int b) {
    int sum = a + b;
    return Math.sqrt(sum) % 1 == 0;
}

private static void swap(int[] arr, int i, int j) {
