public static int squarePermutations(int[] A) {
    int n = A.length;
    Set<Integer> used = new HashSet<>();
    int count = 0;

    public void backtrack(int[] A, int index) {
        if (index == n) {
            count++;
            return;
        }

        for (int i = 0; i < n; i++) {
            if (used.contains(i) || (i > 0 && A[i] == A[i - 1] && !used.contains(i - 1))) {
                continue;
            }
            used.add(i);
            A[index] = A[i];
            backtrack(A, index + 1);
            used.remove(i);
        }
    }

    backtrack(A, 0);
    return count;
}

