public static int squarePermutations(int[] A) {
    if (A == null || A.length <= 1) {
        return A.length == 1 ? 1 : 0;
    }
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (isPerfectSquare(A[i])) {
            count += countSquarePermutationsWithElementRemoved(A, i);
        }
    }
    return count;
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

private static int countSquarePermutationsWithElementRemoved(int[] A, int index) {
    int CaseWithElementWith = 0;
    int CaseWithoutElementWith = 0;

    for (int i = 0; i < A.length; i++) {
        if (i == index) {
            continue;
        }
        if (isPerfectSquare(A[index] + A[i])) {
            int[] newArray = new int[A.length];
            System.arraycopy(A, 0, newArray, 0, index);
            System.arraycopy(A, index + 1, newArray, index, A.length - index - 1);
           CaseWithElementWith += countSquarePermutations(newArray);
        } else {
            CaseWithoutElementWith += countSquarePermutationsWithElementRemoved(A, i);
        }
    }
    return CaseWithElementWith + CaseWithoutElementWith;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] leftSmaller = new int[n];
    int[] rightSmaller = new int[n];
    int[] result = new int[n];

    // Calculate left smaller array
    for (int i = 0; i < n; i++) {
        int j = i - 1;
        while (j >= 0 && heights[j] >= heights[i]) {
            j = leftSmaller[j];
        }
        leftSmaller[i] = j;
    }

    // Calculate right smaller array
    for (int i = n - 1; i >= 0; i--) {
        int j = i + 1;
        while (j < n && heights[j] >= heights[i]) {
            j = rightSmaller[j];
        }
        rightSmaller[i] = j;
    }

    // Calculate maximum area
    for (int i = 0; i < n; i++) {
        result[i] = (rightSmaller[i] - leftSmaller[i] - 1) * heights[i];
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, result[i]);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    int[] stack = new int[heights.length];
    int top = -1;
    for (int i = 0; i < heights.length; i++) {
        while (top >= 0 && heights[stack[top]] >= heights[i]) {
            int height = heights[stack[top]];
            stack[top--];
            int width = stack[top == -1 ? -1 : top + 1];
            maxArea = Math.max(maxArea, height * width);
        }
        stack[++top] = i;
    }
    while (top >= 0) {
        int height = heights[stack[top]];
        stack[top--];
        int width = stack[top == -1 ? -1 : top + 1];
        maxArea = Math.max(maxArea, height * width);
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int area = 0;
    int[] left = new int[heights.length];
    int[] right = new int[heights.length];

    // Find the indices of the nearest smaller element to the left of each bar
    Stack<Integer> stack = new Stack<>();
    for (int i = 0; i < heights.length; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            left[i] = 0;
        } else {
            left[i] = stack.peek() + 1;
        }
        stack.push(i);
    }

    // Find the indices of the nearest smaller element to the right of each bar
    stack.clear();
    for (int i = heights.length - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            right[i] = heights.length - 1;
        } else {
            right[i] = stack.peek() - 1;
        }
        stack.push(i);
    }

    // Calculate the area of each bar and find the maximum area
    for (int i = 0; i < heights.length; i++) {
        area = Math.max(area, (right[i] - left[i] + 1) * heights[i]);
    }

    return area;
}

public static int largestRectangleArea(int[] heights) {
