        int height = heights[stack.pop()];
        int width = stack.isEmpty() ? heights.length : heights.length - stack.peek() - 1;
        result = Math.max(result, height * width);
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int currentRow = 0;
    int currentCol = 0;
    int isDescending = true;

    for (int i = 0; i < rows * cols; i++) {
        result[i] = mat[currentRow][currentCol];

        if (isDescending) {
            if (currentRow + 1 < rows && currentCol - 1 >= 0) {
                currentRow++;
                currentCol--;
            } else if (currentRow + 1 < rows) {
                currentRow++;
            } else {
                isDescending = false;
                currentCol++;
            }
        } else {
            if (currentRow - 1 >= 0 && currentCol + 1 < cols) {
                currentRow--;
                currentCol++;
            } else if (currentCol + 1 < cols) {
                currentCol++;
            } else {
                isDescending = true;
                currentRow--;
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int r = 0, c = 0, d = 1; // 1 for down, -1 for up

    for (int i = 0; i < m * n; i++) {
        result[i] = mat[r][c];

        if (d == 1) {
            r += 1; // Move down
        } else {
            r -= 1; // Move up
        }
        c += d; // Move right

        if (r >= m || r < 0 || c >= n || c < 0) {
            r -= d; // Move back to the previous position
            c -= d; // Move back to the previous position
            if (d == 1) {
                c += 1; // Move right to the next column if direction is up
            } else {
                c -= 1; // Move left to the previous column if direction is down
            }
            d *= -1; // Change the direction
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat.length == 0) {
        return new int[0];
    }

    int[] result = new int[mat.length * mat[0].length];
    int row = 0;
    int col = 0;
    int direction = 1; // 1 for down, -1 for up
    int index = 0;

    while (row < mat.length && col < mat[0].length) {
        result[index++] = mat[row][col];

        if (direction == 1) {
            // Move right
            if (col == mat[0].length - 1) {
                row++;
                direction = -1; // Change direction to up
            } else {
                col++;
            }
        } else {
            // Move left
            if (row == mat.length - 1) {
                col++;
                direction = 1; // Change direction to down
            } else {
                row++;
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int counter = 0;

    // Traverse the first row
    for (int i = 0; i < cols; i++) {
        result[counter++] = mat[0][i];
    }

    // Traverse the last column from bottom to top
    for (int i = 1; i < rows - 1; i++) {
        int j = cols - 1;
        while (j >= 0 && i < rows) {
            result[counter++] = mat[i][j];
            j--;
            i++;
        }
    }

    // Traverse the last row from left to right
    for (int i = cols - 1; i >= 0; i--) {
        result[counter++] = mat[rows - 1][i];
    }

    // Traverse the first column from top to down
    for (int i = 2; i < rows; i++) {
        int j = 0;
        while (j < cols && i < rows) {
            result[counter++] = mat[i][j];
            j++;
            i++;
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    List<Integer> result = new ArrayList<>();
    int m = mat.length;
    int n = mat[0].length;
    int totalElements = m * n;

    for (int i = 0; i < totalElements; i++) {
        int x = i % m;
        int y = i / m;
        if (x >= y) {
            result.add(mat[x][y]);
        } else {
            result.add(mat[m - y - 1][y]);
        }
    }

    return result.stream().mapToInt(Integer::intValue).toArray();
}

public static int findSmallestInteger(int n) {
    if (n <= 1) {
        return -1;
    }

    ArrayList<Integer> digits = new ArrayList<>();
    while (n > 0) {
        digits.add(n % 10);
        n /= 10;
    }

    digits.sort(Comparator.reverseOrder());

    for (int i = 0; i < digits.size() - 1; i++) {
        if (digits.get(i) < digits.get(i + 1)) {
            int temp = digits.get(i);
            digits.set(i, digits.get(i + 1));
            digits.set(i + 1, temp);
            break;
        }
    }

    long sum = 0;
    for (int d : digits) {
        sum = sum * 10 + d;
    }

    if (sum <= n) {
        return -1;
    }

    return (int) sum;
}

public static int findSmallestInteger(int n) {
    int str = String.valueOf(n);
    int s = Integer.parseInt(str);
    int max = 100;

    if (s >= max) {
        return -1;
    } else {
        int maxIndex = s % 10;

        for (int i = s / 10; i >= 0; i--) {
            if (maxIndex < i % 10) {
                int temp = i;
                char[] chars = str.toCharArray();
                chars[maxIndex] = chars[i];
                chars[i] = temp;
                str = new String(chars);
                break;
            }
        }

        if (!str.startsWith("0")) {
            return Integer.parseInt(str);
        } else {
            return -1;
        }
    }
}

public static int findSmallestInteger(int n) {
    int result = -1;
    String numStr = String.valueOf(n);
    int length = numStr.length();

    // Iterate through all possible permutations of the digits
    for (int i = 0; i < length; i++) {
        // Generate a permutation of the digits for the current position
        for (int j = i + 1; j < length; j++) {
            char[] permutation = numStr.toCharArray();
            char temp = permutation[i];
            permutation[i] = permutation[j];
            permutation[j] = temp;

            // Convert the permutation back to an integer
            int permInt = Integer.parseInt(String.valueOf(permutation));

            // Check if the permutation is greater than the original number
            if (permInt > n) {
                if (result == -1 || permInt < result) {
                    result = permInt;
                }
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 9) {
        return -1; // If n is a single digit or less, no smaller integer greater than it can be formed.
    }

    char[] digits = String.valueOf(n).toCharArray();
    int index = n - 1;

    while (true) {
        // Find the maximum digit smaller than index in digits.
        int maxDigit = -1;
        for (int i = index; i >= 0; i--) {
            if (digits[i] > digits[maxDigit]) {
                maxDigit = i;
            }
        }

        // If no such digit is found, no smaller integer greater than n can be formed.
        if (maxDigit == -1) {
            return -1;
        }

        // Find the next smallest digit in digits that is greater than digits[maxDigit].
        int nextDigit = maxDigit + 1;
        for (int i = index; i < digits.length; i++) {
            if (digits[i] > digits[nextDigit] && digits[i] < digits[maxDigit]) {
                nextDigit = i;
            }
        }

        // Swap digits[maxDigit] and digits[nextDigit].
        char temp = digits[maxDigit];
        digits[maxDigit] = digits[nextDigit];
        digits[nextDigit] = temp;

        // Sort the digits after index in ascending order.
        Arrays.sort(digits, index, digits.length);

        // Convert the modified array back to an integer.
        return Integer.parseInt(new String(digits));
    }
}

public static int findSmallestInteger(int n) {
    String s = Integer.toString(n);
    int[] digits = new int[s.length()];
    for (int i = 0; i < s.length(); i++) {
        digits[i] = s.charAt(i) - '0';
    }
    int[] sortedDigits = digits.clone();
    Arrays.sort(sortedDigits);
    boolean found = false;
    do {
        int num = 0;
        for (int i = sortedDigits.length - 1; i >= 0; i--) {
            num = num * 10 + sortedDigits[i];
        }
        if (num <= n) {
            continue;
        }
        found = true;
        break;
    } while (true);
    return found ? num : -1;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n % 2 != 0) {
        result.add(String.valueOf(0));
    }
    for (int i = (n + 1) / 2; i < n; i++) {
        String prefix = "";
        for (int j = 1; j <= i; j++) {
            prefix += String.valueOf((j % 2 == 0) ? '0' : '9');
        }
        result.add(prefix + prefix);
    }
    return result;
}

