public static List<String> centerSymmetricNumbers(int n) {
    List<String> centerSymmetricNumbers = new ArrayList<>();

    if (n == 1) {
        centerSymmetricNumbers.add("0");
        centerSymmetricNumbers.add("1");
        centerSymmetricNumbers.add("8");
        return centerSymmetricNumbers;
    }

    for (int i = 0; i <= n / 2; i++) {
        int mid = i;
        char digit = '1';

        while (mid > 0) {
            digit = (char) ((digit - '0' + 1) % 9 + '0');
            mid--;
        }

        String number = padWithZeros(String.valueOf(digit), n);
        centerSymmetricNumbers.add(number);
    }

    return centerSymmetricNumbers;
}

private static String padWithZeros(String str, int length) {
    while (str.length() < length) {
        str = '0' + str;
    }
    return str;
}

