public static boolean isBoomerang(int[][] points) {
    for (int i = 0; i < points.length - 1; i++) {
        int x = points[i][0];
        int y = points[i][1];
        int nextX = points[i + 1][0];
        int nextY = points[i + 1][1];
        if (x * (nextY - y) + y * (nextX - x) == 0) {
            return false;
        }
    }
    return true;
}

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if any of the points are collinear
    if ((y2 - y1) * (x3 - x2) == (y3 - y2) * (x2 - x1)) {
        return false;
    }

    return true;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("Invalid number of points");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if the points form a right angle using the dot product
    int dotProduct1 = x1 * y2 + x2 * y3 + x3 * y1;
    int dotProduct2 = x1 * (y3 - y2) + x2 * (y1 - y3) + x3 * (y2 - y1);

    return dotProduct1 != 0 && dotProduct2 != 0 && dotProduct1 != dotProduct2;
}

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    return (x1*(y2 - y3) + x2*(y3 - y1) + x3*(y1 - y2)) != 0;
}

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if the points form a valid triangle
    int det = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    // If the determinant is non-zero, the points form a triangle, but if we remove one point,
    // the remaining两个人 would be collinear. If any of the two conditions are met, the points form a boomerang.
    return Math.abs(det) > 0.0;
}

public static int findNthUglyNumber(int n) {
    int[] uglyNumbers = new int[n];
    int p2 = 0, p3 = 0, p5 = 0;
    uglyNumbers[0] = 1;
    for (int i = 1; i < n; i++) {
        int min = Math.min(uglyNumbers[p2] * 2, Math.min(uglyNumbers[p3] * 3, uglyNumbers[p5] * 5));
        uglyNumbers[i] = min;
        if (min == uglyNumbers[p2] * 2) {
            p2++;
        }
        if (min == uglyNumbers[p3] * 3) {
            p3++;
        }
        if (min == uglyNumbers[p5] * 5) {
            p5++;
        }
    }
    return uglyNumbers[n - 1];
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) return 0;

    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0;
    int i3 = 0;
    int i5 = 0;

    int nextMultipleOf2 = ugly[i2] * 2;
    int nextMultipleOf3 = ugly[i3] * 3;
    int nextMultipleOf5 = ugly[i5] * 5;

    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        ugly[i] = nextUgly;

        if (nextUgly == nextMultipleOf2) i2++;
        if (nextUgly == nextMultipleOf3) i3++;
        if (nextUgly == nextMultipleOf5) i5++;

        nextMultipleOf2 = ugly[i2] * 2;
        nextMultipleOf3 = ugly[i3] * 3;
        nextMultipleOf5 = ugly[i5] * 5;
    }

    return ugly[n - 1];
}

