    if (s == null || s.length() == 0) {
        return 0;
    }

    int maxLength = 0;
    int currentLength = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLength++;
            maxLength = Math.max(maxLength, currentLength);
        } else {
            currentLength = 1;
        }
    }

    return maxLength;
}

public static int calculateEnergy(String s) {
    int left = 0, right = 0, maxLength = 0;
    char currentChar = s.charAt(0);

    while (right < s.length()) {
        if (s.charAt(right) == currentChar) {
            right++;
            maxLength = Math.max(maxLength, right - left);
        } else {
            currentChar = s.charAt(right);
            left = right;
        }
    }

    return maxLength;
}

public static int calculateEnergy(String s) {
    int currentEnergy = 1, maxEnergy = 1;
    char prevChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == prevChar) {
            currentEnergy++;
            maxEnergy = Math.max(maxEnergy, currentEnergy);
        } else {
            currentEnergy = 1;
            prevChar = s.charAt(i);
        }
    }

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) return result;

    dfs(result, 1, n);

    return result;
}

private static void dfs(List<Integer> result, int current, int n) {
    if (current > n) return;
    result.add(current);

    for (int i = 0; i <= 9; i++) {
        int next = current * 10 + i;
        dfs(result, next, n);
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    dfs(result, 1, n);
    return result;
}

private static void dfs(List<Integer> result, int current, int n) {
    for (int i = 0; i <= 9 && current * 10 + i <= n; i++) {
        result.add(current * 10 + i);
        dfs(result, current * 10 + i, n);
    }
}

public static List<Integer> lexicalOrder(int n) {
    LinkedList<Integer> result = new LinkedList<>();
    recursiveKMin(result, 0, n);
    return result;
}

public static void recursiveKMin(List<Integer> result, int current, int k) {
    if (current > k) {
        return;
    }
    if (current != 0) {
        result.addFirst(current);
    }
    for (int i = 0; i <= 9; i++) {
        recursiveKMin(result, 10 * current + i, k);
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> list = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        lexicalOrderRecursively(i, list, 1);
    }
    Collections.sort(list);
    return list;
}

private static void lexicalOrderRecursively(int number, List<Integer> list, int level) {
    if (number > n) {
        return;
    }
    list.add(number);
    for (int i = 0; i <= 9; i++) {
        lexicalOrderRecursively(number * 10 + i, list, level + 1);
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int num, int n, List<Integer> result) {
    if (num > n) {
        return;
    }
    result.add(num);
    for (int i = 0; i <= 9; i++) {
        dfs(num * 10 + i, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueElements = new HashSet<>();
    int totalUniqueSum = 0;

    for (int num : nums) {
        if (!uniqueElements.contains(num)) {
            uniqueElements.add(num);
            totalUniqueSum += num;
        }
    }

    return totalUniqueSum;
}

